package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerRegistrationDateInvalidException;

/**
 * Validates the owner's optional {@code registrationDate} WHEN PRESENT: a supplied value must not be
 * later than the server's current date, since a registration cannot be dated in the future. An
 * absent date is left untouched (it later defaults to the server date in {@link BuildOwner}).
 *
 * <p>Reads the body published by {@link RequireOwnerFields}; runs before {@link BuildOwner} so a
 * future date is a 400 via {@link OwnerRegistrationDateInvalidException}, never stored.
 */
public class RequireRegistrationDateNotFuture {

    public void service(@Val OwnerFieldsDto request) throws OwnerRegistrationDateInvalidException {
        LocalDate supplied = request.getRegistrationDate();
        if (supplied != null && supplied.isAfter(LocalDate.now())) {
            throw new OwnerRegistrationDateInvalidException(supplied);
        }
    }
}
======== RequireOwnerPostcode ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerPostcodeInvalidException;

/**
 * Validates the owner's optional {@code postcode} WHEN PRESENT. A supplied postcode must be
 * exactly four digits and, when the owner's city maps to a known region, must fall within that
 * region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
 * region accepts any four-digit postcode. An absent postcode is left untouched — postcode is
 * optional, so the request contract stays backward-compatible.
 *
 * <p>Reads the body published by {@link RequireOwnerFields}; runs before {@link BuildOwner} so an
 * out-of-range postcode is a 400 via {@link OwnerPostcodeInvalidException}, never stored.
 */
public class RequireOwnerPostcode {

    /** City -> region, using the same fixed table as the owner locality mapping. */
    private static final Map<String, String> CITY_REGION =
            Map.of("Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** Region -> inclusive {low, high} 4-digit postcode range. */
    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    public void service(@Val OwnerFieldsDto request) throws OwnerPostcodeInvalidException {
        String postcode = request.getPostcode();
        if (postcode == null) {
            return; // optional when absent
        }
        if (!postcode.matches("[0-9]{4}")) {
            throw new OwnerPostcodeInvalidException(postcode);
        }
        String region = CITY_REGION.get(request.getCity());
        int[] range = region == null ? null : REGION_POSTCODES.get(region);
        if (range != null) {
            int value = Integer.parseInt(postcode);
            if (value < range[0] || value > range[1]) {
                throw new OwnerPostcodeInvalidException(postcode);
            }
        }
    }
}
======== NormalizeOwnerAddress ========
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Normalizes the address of the validated body (published by {@link RequireOwnerFields}) into
 * a canonical form: leading/trailing whitespace is trimmed, internal whitespace runs are
 * collapsed to a single space, the whole value is upper-cased, and common abbreviations are
 * expanded to their full word ({@code ST}&rarr;{@code STREET}, {@code RD}&rarr;{@code ROAD},
 * {@code AVE}&rarr;{@code AVENUE}). The canonical value is written back onto the body in place,
 * so {@link BuildOwner} stores it and later reads/responses return it.
 *
 * <p>Normalization applies to whichever address fields the body supplied: the structured
 * {@code addressLine1}/{@code addressLine2} are preferred when present, otherwise the flat
 * {@code address}. When a structured {@code addressLine1} is supplied the flat {@code address} is
 * replaced with the composed form — the normalized {@code addressLine1} followed, when an
 * {@code addressLine2} is present, by a single space and the normalized {@code addressLine2}.
 *
 * <p>Runs after {@link RequireOwnerFields} — which already rejects a body with no address in
 * either form — and before the household steps, so
 * {@link RequireUniqueOwnerHousehold duplicate detection} and
 * {@link AssignHouseholdId the shared household id} both compare the normalized form.
 */
public class NormalizeOwnerAddress {

    public void service(@Val OwnerFieldsDto request) {
        String line1 = normalize(request.getAddressLine1());
        String line2 = normalize(request.getAddressLine2());
        if (!line1.isEmpty()) {
            // Structured address supplied: normalize the lines and compose the flat address.
            request.setAddressLine1(line1);
            request.setAddressLine2(line2.isEmpty() ? null : line2);
            request.setAddress(compose(line1, line2));
        }
        else {
            request.setAddress(normalize(request.getAddress()));
        }
    }

    /**
     * The composed address: the normalized {@code addressLine1}, with a single space and the
     * normalized {@code addressLine2} appended when the latter is present (non-blank).
     */
    static String compose(String line1, String line2) {
        return line2.isEmpty() ? line1 : line1 + " " + line2;
    }

    /**
     * Trimmed, internal whitespace collapsed to a single space, upper-cased, with common
     * abbreviations expanded to their full word. Returns {@code ""} for a null or blank value.
     * Shared with {@link RequireOwnerFields} so the required-field check rejects an address
     * that is blank after normalization.
     */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
        if (collapsed.isEmpty()) {
            return "";
        }
        String[] tokens = collapsed.split(" ");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < tokens.length; i++) {
            if (i > 0) {
                sb.append(' ');
            }
            sb.append(expand(tokens[i]));
        }
        return sb.toString();
    }

    /** Expands a single upper-cased token when it is a known abbreviation, else returns it. */
    private static String expand(String token) {
        switch (token) {
            case "ST":
                return "STREET";
            case "RD":
                return "ROAD";
            case "AVE":
                return "AVENUE";
            default:
                return token;
        }
    }
}
======== NormalizeOwnerTelephone ========
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerTelephoneInvalidException;

/**
 * Normalizes the telephone of the validated body (published by {@link RequireOwnerFields})
 * into E.164 form: spaces, dashes and brackets are stripped; a leading {@code '+'} with its
 * country code is kept when present, otherwise country code {@code '+61'} is assumed and a
 * single leading {@code '0'} is dropped from the national digits. The result must have 8 to
 * 15 digits after the {@code '+'}, and the national-number length must match the country code
 * ({@code '+61'} requires 9 national digits, {@code '+1'} requires 10). The E.164 value is
 * written back onto the body in place, so
 * {@link BuildOwner} maps it and later reads/responses return it. A telephone that cannot form
 * a valid E.164 number is rejected 400 via {@link OwnerTelephoneInvalidException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws OwnerTelephoneInvalidException {
        String raw = request.getTelephone();
        String e164 = toE164(raw);
        if (e164 == null) {
            throw new OwnerTelephoneInvalidException(raw == null ? "" : raw);
        }
        request.setTelephone(e164);
    }

    /**
     * Converts a telephone into E.164 form, or returns {@code null} when it cannot form a
     * valid E.164 number. Shared with {@link RequireUniqueOwnerTelephone} so stored and new
     * telephones are compared in the same canonical form.
     */
    static String toE164(String raw) {
        if (raw == null) {
            return null;
        }
        // Strip spaces, dashes and brackets (leave a leading '+' and the digits).
        String cleaned = raw.replaceAll("[\\s\\-()]", "").trim();
        String digits;
        if (cleaned.startsWith("+")) {
            // Explicit country code: keep the digits following the '+'.
            digits = cleaned.substring(1);
        } else {
            // No country code: assume '+61', dropping a single leading '0'.
            String national = cleaned;
            if (national.startsWith("0")) {
                national = national.substring(1);
            }
            digits = "61" + national;
        }
        if (!digits.matches("\\d{8,15}")) {
            return null;
        }
        // Country-specific national-number length: '+61' requires 9 national digits,
        // '+1' requires 10. Other country codes keep only the general 8-15 rule above.
        if (digits.startsWith("61")) {
            if (digits.length() - 2 != 9) {
                return null;
            }
        } else if (digits.startsWith("1")) {
            if (digits.length() - 1 != 10) {
                return null;
            }
        }
        return "+" + digits;
    }
}
======== NormalizeOwnerEmail ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerEmailInvalidException;

/**
 * Normalizes the optional email of the validated body in place. Email is optional: a null
 * or blank value is left untouched. When present it must be a syntactically valid address,
 * otherwise it is rejected 400 via {@link OwnerEmailInvalidException}. A valid address is
 * lower-cased in place so {@link BuildOwner}/{@link ApplyOwner} store, and later
 * reads/responses return, the lower-cased form.
 */
public class NormalizeOwnerEmail {

    private static final Pattern EMAIL =
            Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");

    public void service(@Val OwnerFieldsDto request) throws OwnerEmailInvalidException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        if (!EMAIL.matcher(email).matches()) {
            throw new OwnerEmailInvalidException(email);
        }
        request.setEmail(email.toLowerCase());
    }
}
======== RequireNonDisposableOwnerEmail ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Set;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerEmailDisposableException;

/**
 * Rejects the create when the owner's email domain is on the disposable-domain blocklist
 * (mailinator.com, tempmail.com, guerrillamail.com). Email is optional: a null or blank value
 * skips the check. Runs after {@link NormalizeOwnerEmail}, which validates syntax and lower-cases
 * the address, so the domain is compared lower-cased. A blocked domain is rejected 400 via
 * {@link OwnerEmailDisposableException}.
 */
public class RequireNonDisposableOwnerEmail {

    private static final Set<String> BLOCKED_DOMAINS =
            Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");

    public void service(@Val OwnerFieldsDto request) throws OwnerEmailDisposableException {
        String email = request.getEmail();
        if (email == null || email.isBlank()) {
            return;
        }
        int at = email.lastIndexOf('@');
        if (at < 0) {
            return; // syntax already validated upstream; nothing to block
        }
        String domain = email.substring(at + 1).toLowerCase();
        if (BLOCKED_DOMAINS.contains(domain)) {
            throw new OwnerEmailDisposableException(email);
        }
    }
}
======== RequireOwnerCityCapacity ========
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerCityCapacityExceededException;

/**
 * Rejects the create when the owner's {@code city} already contains 50 or more owners,
 * compared case-insensitively (the same match used by the per-city customer-code sequence).
 * A full city is rejected 409 via {@link OwnerCityCapacityExceededException}.
 *
 * <p>Runs before {@link SaveOwner}, so the count reflects only the existing owners, not the
 * one being created.
 */
public class RequireOwnerCityCapacity {

    /** A city may hold at most this many owners. */
    static final long CITY_CAPACITY = 50;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerCityCapacityExceededException {
        String city = request.getCity();
        long inCity = ownerRepository.findAll().stream()
                .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
                .count();
        if (inCity >= CITY_CAPACITY) {
            throw new OwnerCityCapacityExceededException(city);
        }
    }
}
======== RequireDailyOwnerLimit ========
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.OwnerDailyLimitExceededException;

/**
 * Rejects the create when 100 or more owners have already been created on the same business day,
 * counted by {@link Owner#getRegistrationDate() registrationDate} equal to this request's effective
 * business day. The effective date is the supplied (or defaulted) registration date rolled forward
 * off any weekend, matching what {@link BuildOwner} will store. The daily quota is full, so no
 * further owner may be created for that day; it is rejected 429 via
 * {@link OwnerDailyLimitExceededException}.
 *
 * <p>Runs before {@link SaveOwner}, so the count reflects only the existing owners, not the
 * one being created.
 */
public class RequireDailyOwnerLimit {

    /** At most this many owners may be created on any one business day. */
    static final long DAILY_LIMIT = 100;

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws OwnerDailyLimitExceededException {
        LocalDate businessDay = RegistrationDate.effective(request);
        long createdThatDay = ownerRepository.findAll().stream()
                .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
                .count();
        if (createdThatDay >= DAILY_LIMIT) {
            throw new OwnerDailyLimitExceededException(businessDay, createdThatDay);
        }
    }
}

